WHERE stat_code = 'BUFF_ATK' AND item_id = (SELECT id FROM items WHERE code = 'ASADO_SALAMANDRA');
UPDATE item_stat_bonuses SET amount = 12, is_percent = TRUE, description = '+12% de inteligencia durante el combate'
