UPDATE quests SET giver_npc = 'halvar', turn_in_npc = 'halvar', npc_name = 'Halvar', name = 'Tormenta doble', description = '«Hoy los gigantes y los brujos bajaron juntos. Dos y dos, y el camino queda abierto.»',
