SELECT (SELECT id FROM quests WHERE code = 'TUNDRA_SEC_ULRICH'), v.t, v.step, v.target, (SELECT id FROM monsters WHERE code = v.monster), (SELECT id FROM items WHERE code = v.item), v.n, v.params::jsonb, v.descr
