  ('COLLECT_ITEM', 1, NULL, NULL, 'PAN_OFRENDA', 1, NULL, 'Consigue un Pan de Ofrenda (Ilse lo hornea)'),
  ('TALK', 2, 'osvaldo', NULL, NULL, 1, NULL, 'Lleva el pan a Don Osvaldo')
