SELECT (SELECT id FROM quests WHERE code = 'CATACUMBAS_SEC_OSVALDO_3'), i.id, v.qty FROM (VALUES ('HUEVO_POCO_COMUN', 1)) AS v(code, qty) JOIN items i ON i.code = v.code;

